<!DOCTYPE html>
<html lang="zh">
<head>
<meta charset="UTF-8">
<title>预订桌位</title>
<style>
body {font-family: Arial, Helvetica, sans-serif; margin:0; padding:0; background:#f9f9f9; color:#333; line-height:1.6;}
.container {max-width:1200px; margin:auto; padding:20px;}
header {background:#004d40; color:#fff; padding:20px; text-align:center;}
header h1 {margin:0; font-size:2.2em;}
nav {margin-top:10px;}
nav a {color:#fff; margin:0 15px; text-decoration:none; font-size:1.1em;}
nav a:hover {text-decoration:underline;}
