<body>
<div class="container">
<header>
<h1>家味餐厅</h1>
</header>
<nav>
<a href="index.html">首页</a>
<a href="about.html">关于我们</a>
<a href="menu.html">菜单</a>
</nav>
<main>
<h2>预订桌位</h2>
<form id="bookingForm">
<p>姓名：<input type="text" name="name" required placeholder="请输入姓名"></p>
<p>电话：<input type="tel" name="phone" required placeholder="请输入电话"></p>
<p>日期：<input type="date" name="date" required></p>
<p>时间：<input type="time" name="time" required></p>
<p>人数：<input type="number" name="party" min="1" max="10" required></p>
<p><button type="button" onclick="submitForm()">提交预订</button></p>
</form>
<script>
function submitForm() {
  var name = document.querySelector('input[name="name"]').value;
  var phone = document.querySelector('input[name="phone"]').value;
  var date = document.querySelector('input[name="date"]').value;
  var time = document.querySelector('input[name="time"]').value;
  var party = document.querySelector('input[name="party"]').value;
  if (!name || !phone || !date || !time || !party) {
    alert("请完整填写所有信息");
    return;
  }
  alert("谢谢！我们已收到您的预订请求，将在24小时内与您联系。");
}
</script>
</main>
<footer>
© 2025 家味餐厅 版权所有
</footer>
</div>
</body>
</html>
